    _copy_present(out, raw, 'cloudSecurityIdentifier')
    if 'isBuiltIn' in raw:
        out['isSystem'] = raw['isBuiltIn']
    if 'isEnabled' in raw:
        out['roleDisabled'] = not raw['isEnabled']
    return out


